157	async fn start_tun(state: State<'_, AppState>) -> Result<String, String> {
158	    let config = state.tun_config.lock().await;
159	    if !config.enabled {
160	        return Err("TUN模式未启用，请在配置中启用".to_string());
161	    }
162	    let tun_config = config.clone();
163	    drop(config);
164	
165	    // 检查是否已在启动中
166	    {
167	        let starting = state.tun_starting.lock().await;
168	        if *starting {
169	            return Ok("TUN正在启动中...".to_string());
170	        }
171	    }
172	
173	    // 设置启动中状态
174	    {
175	        let mut starting = state.tun_starting.lock().await;
176	        *starting = true;
177	    }
178	
179	    // 克隆需要的 Arc 字段
180	    let tun_device = state.tun_device.clone();
181	    let tun_starting = state.tun_starting.clone();
182	    let server = state.server.clone();
183	
184	    // 异步启动TUN
185	    tokio::spawn(async move {
186	        let result = start_tun_internal(tun_device.clone(), server, tun_config).await;
187	        let mut starting = tun_starting.lock().await;
188	        *starting = false;
189	
190	        match result {
191	            Ok(_) => tracing::info!("TUN异步启动完成"),
192	            Err(e) => tracing::error!("TUN异步启动失败: {}", e),
193	        }
194	    });
195	
196	    Ok("TUN正在启动...".to_string())
197	}
