391	/// 测试 DoT (DNS-over-TLS) 连接
392	async fn test_dot_connection(ip: &str, port: u16, query: &[u8]) -> Result<Vec<u8>, String> {
393	    use tokio::io::{AsyncReadExt, AsyncWriteExt};
394	    use tokio::net::TcpStream;
395	    use tokio_rustls::TlsConnector;
396	
397	    let addr = format!("{}:{}", ip, port);
398	
399	    // 建立 TCP 连接
400	    let tcp = match tokio::time::timeout(std::time::Duration::from_secs(3), TcpStream::connect(&addr)).await {
401	        Ok(Ok(stream)) => stream,
402	        Ok(Err(e)) => return Err(format!("TCP连接失败: {}", e)),
403	        Err(_) => return Err("TCP连接超时".to_string()),
404	    };
405	
406	    // 配置 TLS
407	    let mut root_store = rustls::RootCertStore::empty();
408	    root_store.extend(webpki_roots::TLS_SERVER_ROOTS.iter().cloned());
409	    let config = rustls::ClientConfig::builder()
410	        .with_root_certificates(root_store)
411	        .with_no_client_auth();
412	
413	    let connector = TlsConnector::from(std::sync::Arc::new(config));
414	
415	    // TLS 握手
416	    let domain = rustls::pki_types::ServerName::try_from(ip.to_string())
417	        .map_err(|e| format!("无效域名: {}", e))?;
418	
419	    let mut tls = match tokio::time::timeout(std::time::Duration::from_secs(3), connector.connect(domain, tcp)).await {
420	        Ok(Ok(stream)) => stream,
421	        Ok(Err(e)) => return Err(format!("TLS握手失败: {}", e)),
422	        Err(_) => return Err("TLS握手超时".to_string()),
423	    };
424	
425	    // 发送 DNS 查询（DoT 使用 TCP 格式：2字节长度前缀 + 查询数据）
426	    let len = (query.len() as u16).to_be_bytes();
427	    tls.write_all(&len).await.map_err(|e| format!("发送长度失败: {}", e))?;
428	    tls.write_all(query).await.map_err(|e| format!("发送查询失败: {}", e))?;
429	
430	    // 读取响应长度
431	    let mut len_buf = [0u8; 2];
432	    tls.read_exact(&mut len_buf).await.map_err(|e| format!("读取响应长度失败: {}", e))?;
433	    let resp_len = u16::from_be_bytes(len_buf) as usize;
434	
435	    if resp_len > 4096 {
436	        return Err(format!("响应长度异常: {}", resp_len));
437	    }
438	
439	    // 读取响应数据
440	    let mut resp_buf = vec![0u8; resp_len];
441	    match tokio::time::timeout(std::time::Duration::from_secs(3), tls.read_exact(&mut resp_buf)).await {
442	        Ok(Ok(_)) => Ok(resp_buf),
443	        Ok(Err(e)) => Err(format!("读取响应失败: {}", e)),
444	        Err(_) => Err("读取响应超时".to_string()),
445	    }
446	}
