448	fn build_dns_query(domain: &str) -> Vec<u8> {
449	    // 简单构造DNS查询包
450	    let mut packet = Vec::new();
451	
452	    // Transaction ID
453	    packet.extend_from_slice(&[0x12, 0x34]);
454	
455	    // Flags: standard query
456	    packet.extend_from_slice(&[0x01, 0x00]);
457	
458	    // Questions: 1
459	    packet.extend_from_slice(&[0x00, 0x01]);
460	
461	    // Answer RRs: 0
462	    packet.extend_from_slice(&[0x00, 0x00]);
463	
464	    // Authority RRs: 0
465	    packet.extend_from_slice(&[0x00, 0x00]);
466	
467	    // Additional RRs: 0
468	    packet.extend_from_slice(&[0x00, 0x00]);
469	
470	    // Query name
471	    for part in domain.split('.') {
472	        packet.push(part.len() as u8);
473	        packet.extend_from_slice(part.as_bytes());
474	    }
475	    packet.push(0); // root label
476	
477	    // Query type: A (1)
478	    packet.extend_from_slice(&[0x00, 0x01]);
479	
480	    // Query class: IN (1)
481	    packet.extend_from_slice(&[0x00, 0x01]);
482	
483	    packet
484	}
