487	pub fn run() {
488	    tracing_subscriber::fmt()
489	        .with_env_filter(
490	            tracing_subscriber::EnvFilter::try_from_default_env()
491	                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
492	        )
493	        .init();
494	
495	    let config = AppConfig::load();
496	    let server = DnsServer::new(config.clone());
497	    let tun_config = config.tun.clone();
498	    let tun_device = TunDevice::new(tun_config.clone());
499	
500	    let latency_results = Arc::new(Mutex::new(Vec::new()));
501	    let latency_last_test = Arc::new(Mutex::new(None));
502	
503	    // 如果 TUN 配置为启用，初始化时就设置启动中状态
504	    let tun_starting = Arc::new(Mutex::new(tun_config.enabled));
505	
506	    let state = AppState {
507	        server: Arc::new(Mutex::new(server)),
508	        config: Arc::new(Mutex::new(config)),
509	        tun_device: Arc::new(Mutex::new(tun_device)),
510	        tun_config: Arc::new(Mutex::new(tun_config)),
511	        tun_starting,
512	        latency_results: latency_results.clone(),
513	        latency_last_test: latency_last_test.clone(),
514	    };
515	
516	    tauri::Builder::default()
517	        .plugin(tauri_plugin_shell::init())
518	        .manage(state)
519	        .setup(|app| {
520	            // 创建系统托盘菜单
521	            let dns_status = MenuItemBuilder::with_id("dns_status", "DNS: 检查中...")
522	                .enabled(false)
523	                .build(app)?;
524	            let tun_status = MenuItemBuilder::with_id("tun_status", "TUN: 检查中...")
525	                .enabled(false)
526	                .build(app)?;
527	            let latency_info = MenuItemBuilder::with_id("latency_info", "延迟: 未测试")
528	                .enabled(false)
529	                .build(app)?;
530	            let restart_dns = MenuItemBuilder::with_id("restart_dns", "重启 DNS 服务")
531	                .build(app)?;
532	            let restart_tun = MenuItemBuilder::with_id("restart_tun", "重启 TUN")
533	                .build(app)?;
534	            let test_latency = MenuItemBuilder::with_id("test_latency", "测试延迟")
535	                .build(app)?;
536	            let show_window = MenuItemBuilder::with_id("show_window", "显示窗口")
537	                .build(app)?;
538	            let quit = MenuItemBuilder::with_id("quit", "退出")
539	                .build(app)?;
540	
541	            let menu = MenuBuilder::new(app)
542	                .item(&dns_status)
